import { parseCliArgs } from './argv.mjs';
import { runPythonExecutable } from './executableBridge.mjs';

function writeBuffer(stream, value) {
  if (value && value.length > 0) {
    stream.write(value);
  }
}

export function runCli(argv, io = {}) {
  const stdout = io.stdout ?? process.stdout;
  const stderr = io.stderr ?? process.stderr;
  const scriptPath = io.scriptPath ?? process.argv[1] ?? 'test2.mjs';
  const parsed = parseCliArgs(argv, scriptPath);

  if (parsed.kind === 'help') {
    stdout.write(parsed.text);
    return 0;
  }

  if (parsed.kind === 'error') {
    stderr.write(parsed.text);
    return parsed.exitCode;
  }

  const execution = runPythonExecutable(argv);

  if (execution.kind === 'error') {
    stderr.write(`${execution.message}\n`);
    return 1;
  }

  writeBuffer(stdout, execution.stdout);
  writeBuffer(stderr, execution.stderr);
  return execution.status;
}

