import { spawnSync } from 'node:child_process';
import { PYTHON_EXECUTABLE_PATH } from './constants.mjs';

export function runPythonExecutable(argv) {
  const result = spawnSync(PYTHON_EXECUTABLE_PATH, argv, { encoding: null });

  if (result.error) {
    return { kind: 'error', message: result.error.message };
  }

  return {
    kind: 'ok',
    status: result.status ?? 1,
    stdout: result.stdout ?? Buffer.alloc(0),
    stderr: result.stderr ?? Buffer.alloc(0),
  };
}

