import { OPTION_NAME } from './constants.mjs';
import {
  buildExpectedArgumentError,
  buildHelpText,
  buildRequiredArgumentError,
  buildUnrecognizedArgumentsError,
} from './helpText.mjs';

function isNegativeNumberToken(token) {
  if (typeof token !== 'string' || token.length < 2 || token[0] !== '-' || token[1] === '-') {
    return false;
  }

  return !Number.isNaN(Number(token));
}

function isOptionLikeToken(token) {
  return typeof token === 'string' && token.startsWith('-') && !isNegativeNumberToken(token);
}

export function parseCliArgs(argv, scriptPath) {
  let optionA;
  let hasOptionA = false;
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '-h' || token === '--help') {
      return { kind: 'help', text: buildHelpText(scriptPath) };
    }

    if (token === '--') {
      extras.push(...argv.slice(index));
      break;
    }

    if (token === OPTION_NAME) {
      const nextToken = argv[index + 1];

      if (nextToken === undefined || nextToken === '--' || isOptionLikeToken(nextToken)) {
        return { kind: 'error', exitCode: 2, text: buildExpectedArgumentError(scriptPath) };
      }

      optionA = nextToken;
      hasOptionA = true;
      index += 1;
      continue;
    }

    if (typeof token === 'string' && token.startsWith(`${OPTION_NAME}=`)) {
      optionA = token.slice(OPTION_NAME.length + 1);
      hasOptionA = true;
      continue;
    }

    extras.push(token);
  }

  if (!hasOptionA) {
    return { kind: 'error', exitCode: 2, text: buildRequiredArgumentError(scriptPath) };
  }

  if (extras.length > 0) {
    return { kind: 'error', exitCode: 2, text: buildUnrecognizedArgumentsError(scriptPath, extras) };
  }

  return { kind: 'ok', optionA };
}

